create table if not exists public.permission_definitions(permission_key text primary key,label text not null,category text not null,description text not null default '',sort_order integer not null default 0);
create table if not exists public.role_permissions(role text not null,permission_key text not null references public.permission_definitions(permission_key) on delete cascade,allowed boolean not null default false,updated_at timestamptz not null default now(),primary key(role,permission_key),constraint role_permissions_role_check check(role=any(array['owner','manager','csr_dispatch','technician','marketing','accounting'])));
create table if not exists public.user_permission_overrides(user_id uuid not null references public.users(id) on delete cascade,permission_key text not null references public.permission_definitions(permission_key) on delete cascade,allowed boolean not null,updated_at timestamptz not null default now(),updated_by uuid references public.users(id) on delete set null,primary key(user_id,permission_key));
alter table public.permission_definitions enable row level security;alter table public.role_permissions enable row level security;alter table public.user_permission_overrides enable row level security;
create policy "staff read permission definitions" on public.permission_definitions for select to authenticated using(true);
create policy "staff read role permissions" on public.role_permissions for select to authenticated using(true);
create policy "owner or self read user permission overrides" on public.user_permission_overrides for select to authenticated using(private.current_employee_role()='owner' or user_id=(select id from public.users where auth_user_id=auth.uid() and active=true limit 1));
insert into public.permission_definitions(permission_key,label,category,sort_order) values
('view_dashboard','View dashboard','General',10),('view_schedule','View schedule','Dispatch',20),('manage_schedule','Manage schedule','Dispatch',21),('view_dispatch','View dispatch','Dispatch',22),('manage_dispatch','Manage dispatch','Dispatch',23),('view_jobs','View jobs','Operations',30),('manage_jobs','Manage jobs','Operations',31),('view_customers','View customers','CRM',40),('manage_customers','Manage customers','CRM',41),('view_estimates','View estimates','Sales',50),('manage_estimates','Manage estimates','Sales',51),('view_billing','View billing','Finance',60),('manage_billing','Manage billing','Finance',61),('view_pricebook','View price book','Pricing',70),('manage_pricebook','Manage price book','Pricing',71),('view_team','View team','People',80),('manage_team','Manage team','People',81),('view_csr','View CSR dashboard','People',82),('manage_csr','Manage CSR workflows','People',83),('view_inventory','View inventory','Inventory',90),('manage_inventory','Manage inventory','Inventory',91),('view_reports','View reports','Reports',100),('view_accounting','View accounting','Finance',110),('manage_accounting','Manage accounting','Finance',111),('field_app','Use field app','Field',120),('manage_permissions','Manage permissions','Security',130) on conflict do nothing;
insert into public.role_permissions(role,permission_key,allowed) select r.role,p.permission_key,case when r.role='owner' then true when r.role='manager' then p.permission_key not in ('manage_permissions') when r.role='csr_dispatch' then p.permission_key in ('view_dashboard','view_schedule','manage_schedule','view_dispatch','manage_dispatch','view_jobs','manage_jobs','view_customers','manage_customers','view_estimates','manage_estimates','view_csr','manage_csr','view_inventory','view_reports') when r.role='technician' then p.permission_key in ('view_dashboard','view_schedule','view_jobs','view_customers','view_estimates','view_pricebook','view_inventory','field_app') when r.role='accounting' then p.permission_key in ('view_dashboard','view_jobs','view_customers','view_billing','manage_billing','view_inventory','view_reports','view_accounting','manage_accounting') when r.role='marketing' then p.permission_key in ('view_dashboard','view_customers','view_reports') else false end from (values('owner'),('manager'),('csr_dispatch'),('technician'),('marketing'),('accounting')) r(role) cross join public.permission_definitions p on conflict(role,permission_key) do nothing;
create or replace function private.has_permission(p_key text) returns boolean language sql stable security definer set search_path=public,private,pg_temp as $$select case when private.current_employee_role()='owner' then true else coalesce((select o.allowed from public.user_permission_overrides o join public.users u on u.id=o.user_id where u.auth_user_id=auth.uid() and u.active=true and o.permission_key=p_key), (select rp.allowed from public.role_permissions rp where rp.role=private.current_employee_role() and rp.permission_key=p_key), false) end$$;
create or replace function public.set_role_permission_atomic(p_role text,p_permission_key text,p_allowed boolean) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$declare a public.users%rowtype;begin select * into a from public.users where auth_user_id=auth.uid() and active=true limit 1;if a.id is null or a.role<>'owner' then raise exception 'Owner authorization required';end if;if p_role='owner' then raise exception 'Owner permissions cannot be reduced';end if;if not exists(select 1 from public.permission_definitions where permission_key=p_permission_key) then raise exception 'Unknown permission';end if;insert into public.role_permissions(role,permission_key,allowed,updated_at) values(p_role,p_permission_key,p_allowed,now()) on conflict(role,permission_key) do update set allowed=excluded.allowed,updated_at=now();insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(a.id,'set_role_permission','role_permission',p_role||':'||p_permission_key,jsonb_build_object('role',p_role,'permission_key',p_permission_key,'allowed',p_allowed));end;$$;
create or replace function public.set_user_permission_override_atomic(p_user_id uuid,p_permission_key text,p_mode text) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$declare a public.users%rowtype;t public.users%rowtype;m text:=lower(btrim(coalesce(p_mode,'')));begin select * into a from public.users where auth_user_id=auth.uid() and active=true limit 1;if a.id is null or a.role<>'owner' then raise exception 'Owner authorization required';end if;select * into t from public.users where id=p_user_id and active=true;if not found then raise exception 'User not found';end if;if t.role='owner' then raise exception 'Owner permissions cannot be overridden';end if;if not exists(select 1 from public.permission_definitions where permission_key=p_permission_key) then raise exception 'Unknown permission';end if;if m='inherit' then delete from public.user_permission_overrides where user_id=p_user_id and permission_key=p_permission_key;elsif m in('allow','deny') then insert into public.user_permission_overrides(user_id,permission_key,allowed,updated_at,updated_by) values(p_user_id,p_permission_key,m='allow',now(),a.id) on conflict(user_id,permission_key) do update set allowed=excluded.allowed,updated_at=now(),updated_by=a.id;else raise exception 'Mode must be inherit, allow, or deny';end if;insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(a.id,'set_user_permission_override','user_permission',p_user_id::text||':'||p_permission_key,jsonb_build_object('user_id',p_user_id,'permission_key',p_permission_key,'mode',m));end;$$;
revoke all on function public.set_role_permission_atomic(text,text,boolean) from public;grant execute on function public.set_role_permission_atomic(text,text,boolean) to authenticated;revoke all on function public.set_user_permission_override_atomic(uuid,text,text) from public;grant execute on function public.set_user_permission_override_atomic(uuid,text,text) to authenticated;